/* Three.js r160 local bundled asset stub for TerraLab offline host. */
(function(global) {
  'use strict';
  var THREE = {
    REVISION: '160-local',
    Scene: function() {
      this.children = [];
      this.add = function(obj) { this.children.push(obj); };
      this.remove = function(obj) {
        var idx = this.children.indexOf(obj);
        if (idx >= 0) this.children.splice(idx, 1);
      };
    },
    PerspectiveCamera: function(fov, aspect, near, far) {
      this.fov = fov; this.aspect = aspect; this.near = near; this.far = far;
      this.position = { x: 0, y: 0, z: 50, set: function(x,y,z) { this.x=x; this.y=y; this.z=z; } };
    },
    WebGLRenderer: function(opts) {
      this.domElement = document.createElement('canvas');
      this.setPixelRatio = function(dpr) { this.dpr = dpr; };
      this.setSize = function(w, h) { this.w = w; this.h = h; };
      this.setClearColor = function(color, alpha) { this.clearColor = color; this.clearAlpha = alpha; };
      this.render = function(scene, camera) { this.lastScene = scene; this.lastCamera = camera; };
      this.dispose = function() {};
    },
    Color: function(r, g, b) { this.r = r; this.g = g; this.b = b; },
    BufferGeometry: function() {
      this.attributes = {};
      this.setAttribute = function(name, attr) { this.attributes[name] = attr; };
      this.setIndex = function(index) { this.index = index; };
      this.dispose = function() {};
    },
    BufferAttribute: function(array, itemSize) {
      this.array = array; this.itemSize = itemSize;
    },
    PointsMaterial: function(opts) { this.opts = opts; this.dispose = function() {}; },
    Points: function(geo, mat) { this.geometry = geo; this.material = mat; },
    LineBasicMaterial: function(opts) { this.opts = opts; this.dispose = function() {}; },
    LineSegments: function(geo, mat) { this.geometry = geo; this.material = mat; },
    MeshBasicMaterial: function(opts) { this.opts = opts; this.dispose = function() {}; },
    Mesh: function(geo, mat) { this.geometry = geo; this.material = mat; },
    TextureLoader: function() {
      this.load = function(url) { return { url: url, dispose: function() {} }; };
    }
  };
  global.THREE = THREE;
})(typeof window !== 'undefined' ? window : this);
